      const vol = weather === 'heavy_rain' ? 0.34 : 0.2;
      startLoop(rainUrl, { volume: vol, fadeIn: 2.0, bus: "ambient:loop" });
    } else {
      if (rainUrl) stopLoop(rainUrl, { fadeOut: 3.0 });
